package com.retailflow.pos.backup;
import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class BackupScheduler{private static final Logger log=LoggerFactory.getLogger(BackupScheduler.class);private final BackupService backup;private final GoogleDriveService drive;private final boolean enabled;private final int keepCount,keepDays;public BackupScheduler(BackupService backup,GoogleDriveService drive,@Value("${backup.auto-enabled:true}")boolean enabled,@Value("${backup.keep-local-count:5}")int keepCount,@Value("${backup.keep-local-days:30}")int keepDays){this.backup=backup;this.drive=drive;this.enabled=enabled;this.keepCount=keepCount;this.keepDays=keepDays;}@Scheduled(cron="0 0 2 * * *")public void scheduledBackup(){if(!enabled)return;try{var result=backup.exportToLocal(null);if(drive.isAuthorized())drive.uploadBackup(result.path());backup.deleteOld(keepCount,keepDays);log.info("Scheduled backup completed: {}",result.filename());}catch(Exception e){log.error("Scheduled backup failed",e);}}}
